# isolation: min manhattan dist between different comps
def iso(cs):
    res={}
    for a,(ca,ca_cells) in enumerate(cs):
        best=10**9
        for b,(cb,cb_cells) in enumerate(cs):
            if a==b: continue
            for (x,y) in ca_cells:
                for (u,v) in cb_cells:
                    d=abs(x-u)+abs(y-v)
                    if d<best: best=d
        res[(ca,tuple(sorted(ca_cells))[:1],len(ca_cells))]=best
    return res
