def point_dirs(comp_cells, color):
    """pointing directions by shape type: line->axis dirs, L(arms>=2)->4 axis ext, arrow->shaft, else none"""
    cells=set(comp_cells)
    rs=[r for r,c in cells]; cs_=[c for r,c in cells]
    h=len(set(rs))==1; v=len(set(cs_))==1
    n=len(cells)
    if n==1: return []
    if h: return [(0,1),(0,-1)]
    if v: return [(1,0),(-1,0)]
    # find corner: cell whose removal... L detection: cell with two perpendicular neighbors both in comp, arms>=2
    for (r,c) in cells:
        for (dr,dc) in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            # corner with arms going (dr,0) and (0,dc)
            a1=all((r+dr*k,c) in cells for k in (1,2))
            a2=all((r,c+dc*k) in cells for k in (1,2))
            if a1 and a2 and (r-dr,c-dc) not in cells and (r,c-dc) not in cells and (r-dr,c) not in cells:
                ext=[]
                for d in [(dr,0),(-dr,0),(0,dc),(0,-dc)]:
                    ext.append(d)
                return ext
    return []  # blobs/arrows-without-detection: no simple pointing

def march(g,cells,start,d,bg):
    r,c=start
    H,W=len(g),len(g[0])
    r+=d[0]; c+=d[1]
    while 0<=r<H and 0<=c<W:
        if (r,c) not in cells and g[r][c]!=bg:
            return (r,c)
        r+=d[0]; c+=d[1]
    return None

def find_L(cs):
    Ls=[]
    for col,cc in cs:
        ds=point_dirs(cc,col)
        # point_dirs returns 4 dirs only for L; distinguish: recheck
        cells=set(cc)
        isl=False
        for (r,c) in cells:
            for (dr,dc) in [(1,1),(1,-1),(-1,1),(-1,-1)]:
                if all((r+dr*k,c) in cells for k in (1,2)) and all((r,c+dc*k) in cells for k in (1,2)):
                    isl=True
        if isl and len(cc)>=5: Ls.append((col,cc))
    return Ls

def transform(g):
    g=norm(g); H,W=len(g),len(g[0])
    bgs={}
    from collections import Counter
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    cs=comps4(g,bg)
    out=[list(r) for r in g]
    Ls=find_L(cs)
    if not Ls: return out
    col,Lc = max(Ls,key=lambda x:len(x[1]))  # unique L expected
    Lset=set(Lc)
    # mutual partner: L marches along its 4 axis extensions, hits obj; obj points back hitting L
    comp_of={}
    for i,(c2_,cc) in enumerate(cs): 
        for cell in cc: comp_of[cell]=i
    mutual=None
    for d in point_dirs(Lc,col):
        hit=march(g,Lset,Lc[0] if False else list(Lc)[0],d,bg)  # start from corner? need per-arm; approximate: from each L cell
    # better: march from every L cell in every axis dir, skipping own comp
    hits=set()
    for (r,c) in Lc:
        for d in [(1,0),(-1,0),(0,1),(0,-1)]:
            h=march(g,Lset,(r,c),d,bg)
            if h: hits.add(h)
    for hcell in hits:
        ti=comp_of[hcell]
        tcol,tcc=cs[ti]
        if tcol==2: continue
        tset=set(tcc)
        for d in point_dirs(tcc,tcol):
            hh=march(g,tset,list(tcc)[0],d,bg)
        # march from every cell of target
        for (r,c) in tcc:
            for d in point_dirs(tcc,tcol) or []:
                hh=march(g,tset,(r,c),d,bg)
                if hh and hh in Lset:
                    mutual=(ti,tcol,tcc)
    if mutual:
        ti,tcol,tcc=mutual
        for (r,c) in tcc: out[r][c]=col
    else:
        # fallback: smallest non-2 object, tie -> most isolated
        isod=iso(cs)
        cands=[(c2_,cc) for c2_,cc in cs if c2_!=2]
        def key(item):
            c2_,cc=item
            return (len(cc), -isod[(c2_,(list(sorted(cc))[0],),len(cc))])
        tgt=min(cands,key=key)
        for (r,c) in tgt[1]: out[r][c]=col
    return out

