from collections import Counter

def exact_L(cc):
    cells=set(cc); n=len(cells)
    for (r,c) in cells:
        for dr in (1,-1):
            for dc in (1,-1):
                a=0
                while (r+dr*(a+1),c) in cells: a+=1
                b=0
                while (r,c+dc*(b+1)) in cells: b+=1
                if a>=2 and b>=2 and 1+a+b==n: return (r,c,dr,dc,a,b)
    return None

def shape_point_dirs(cc):
    """pointing dirs: line->axis, exact-L->4 arm-axis dirs, arrow->shaft dirs, else none"""
    cells=set(cc)
    rs={r for r,c in cells}; cs_={c for r,c in cells}
    if len(cells)==1: return []
    if len(rs)==1: return [(0,1),(0,-1)]
    if len(cs_)==1: return [(1,0),(-1,0)]
    L=exact_L(cc)
    if L: return [(1,0),(-1,0),(0,1),(0,-1)]
    # arrow: a maximal straight run (shaft, len>=3) + perpendicular run (head, len>=2) at shaft end; comp==shaft+head
    # try all orientations/diagonals
    for d in [(0,1),(1,0),(1,1),(1,-1)]:
        # find shaft cells: lines in direction d
        # build runs
        rem=set(cells)
        runs=[]
        while rem:
            s=rem.pop()
            run={s}
            for sgn in (1,-1):
                k=1
                while (s[0]+d[0]*k*sgn, s[1]+d[1]*k*sgn) in rem:
                    run.add((s[0]+d[0]*k*sgn, s[1]+d[1]*k*sgn)); k+=1
            rem-=run
            runs.append(run)
        for run in runs:
            if len(run)>=3:
                pe=perp=[(d[1],d[0]),(-d[1],-d[0])]
                for e in run:
                    for pd in perp:
                        head=set()
                        k=1
                        while (e[0]+pd[0]*k, e[1]+pd[1]*k) in cells:
                            head.add((e[0]+pd[0]*k, e[1]+pd[1]*k)); k+=1
                        if len(head)>=2 and (run|head)==cells and (e[0]-pd[0],e[1]-pd[1]) not in cells:
                            # shaft extends opposite pd from e
                            return [tuple(-x for x in d), d]
    return []

def march(g,own,start,d,bg):
    r,c=start[0]+d[0],start[1]+d[1]
    H,W=len(g),len(g[0])
    while 0<=r<H and 0<=c<W:
        if (r,c) not in own and g[r][c]!=bg: return (r,c)
        r+=d[0]; c+=d[1]
    return None

def transform(g):
    g=norm(g); H,W=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    cs=comps4(g,bg)
    out=[list(r) for r in g]
    Ls=[(col,cc) for col,cc in cs if exact_L(cc)]
    if not Ls: return out
    col,Lc=max(Ls,key=lambda x:len(x[1]))
    Lset=set(Lc)
    comp_of={}
    for idx,(c2,cc) in enumerate(cs):
        for cell in cc: comp_of[cell]=idx
    target=None
    # 1) L's axis rays hit a pointing comp that points back (anti-parallel along its own pointing)
    for (r,c) in Lc:
        for d in [(1,0),(-1,0),(0,1),(0,-1)]:
            h=march(g,Lset,(r,c),d,bg)
            if h:
                ti=comp_of[h]; tcol,tcc=cs[ti]
                if tcol==2: continue
                tset=set(tcc)
                for pd in shape_point_dirs(tcc):
                    hh=march(g,tset,h,pd,bg)
                    if hh in Lset: target=(ti,tcol,tcc)
    # 2) any comp's pointing ray hits the L (arrow pointing at L)
    if target is None:
        for ti,(tcol,tcc) in enumerate(cs):
            if tcol==2 or (tcol,cc2)==(col,Lc) if False else (tcol==col and set(tcc)==Lset): continue
            tset=set(tcc)
            for (r,c) in tcc:
                for pd in shape_point_dirs(tcc):
                    hh=march(g,tset,(r,c),pd,bg)
                    if hh in Lset: target=(ti,tcol,tcc)
    if target:
        for (r,c) in target[2]: out[r][c]=col
    else:
        cands=[(c2,cc) for c2,cc in cs if c2!=2]
        isod={}
        for a,(ca,ca_cells) in enumerate(cs):
            best=10**9
            for b,(cb,cb_cells) in enumerate(cs):
                if a==b: continue
                for (x,y) in ca_cells:
                    for (u,v) in cb_cells:
                        best=min(best,abs(x-u)+abs(y-v))
            isod[a]=best
        idx={id(cc):i for i,(c2,cc) in enumerate(cs)}
        tgt=min(cands,key=lambda it:(len(it[1]),-isod[idx[id(it[1])]]))
        for (r,c) in tgt[1]: out[r][c]=col
    return out

