prog='''import sys
from collections import Counter, deque

def comps4(g, bg):
    R, C = len(g), len(g[0])
    seen = [[False]*C for _ in range(R)]
    out = []
    for r in range(R):
        for c in range(C):
            if not seen[r][c] and g[r][c] != bg:
                col = g[r][c]; cells = []
                q = deque([(r, c)]); seen[r][c] = True
                while q:
                    x, y = q.popleft(); cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and g[nx][ny] == col:
                            seen[nx][ny] = True; q.append((nx, ny))
                out.append((col, cells))
    return out

def exact_L(cells):
    s = set(cells); rs = [r for r,_ in cells]; cs = [c for _,c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    for cr, cc, dr, dc in ((r0,c0,1,1),(r0,c1,1,-1),(r1,c0,-1,1),(r1,c1,-1,-1)):
        if (cr,cc) not in s: continue
        arm1 = [(cr, cc + i*dc) for i in range(2, 100) if (cr, cc+i*dc) in s]
        arm2 = [(cr + i*dr, cc) for i in range(2, 100) if (cr+i*dr, cc) in s]
        if len(arm1) >= 1 and len(arm2) >= 1 and len(arm1)+len(arm2)+1 == len(cells) \
           and all((cr, cc+i*dc) in s for i in range(len(arm1)+1)) \
           and all((cr+i*dr, cc) in s for i in range(len(arm2)+1):
            pass
    return False

def norm_shape(cells):
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    return tuple(sorted((r-min(rs), c-min(cs)) for r,c in cells))

def transform(grid):
    g=[list(r) for r in grid]
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps4(g,bg)
    # L = largest exact-L comp
    Lc=None
    for col,cal in cs:
        s=set(cal); rs=[r for r,_ in cal]; csl=[c for _,c in cal]
        r0,r1,c0,c1=min(rs),max(rs),min(csl),max(csl)
        for cr,cc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            if (cr,cc) in s:
                arms=[d for d in ((0,1),(0,-1),(1,0),(-1,0))]
                ok=False
                for d1 in arms:
                    for d2 in arms:
                        if d1[0]*d2[0]+d1[1]*d2[1]!=0: continue
                        a1=[];a2=[];x,y=cr+d1[0],cc+d1[1]
                        while 0<=x<len(g) and 0<=y<len(g[0]) and (x,y) in s:
                            a1.append((x,y)); x+=d1[0]; y+=d1[1]
                        x,y=cr+d2[0],cc+d2[1]
                        while 0<=x<len(g) and 0<=y<len(g[0]) and (x,y) in s:
                            a2.append((x,y)); x+=d2[0]; y+=d2[1]
                        if len(a1)>=2 and len(a2)>=2 and len(a1)+len(a2)+1==len(cal) and set(a1)|set(a2)|{(cr,cc)}==s:
                            ok=True
                if ok: Lc=(col,cal,(cr,cc))
    if Lc is None: return g
    Lcol,Lcal,(cr,cc)=Lc
    Lset=set(Lcal)
    others=[(col,cal) for col,cal in cs if set(cal)!=Lset]
    # exact-shape duplicate pairs: paint the one farther from L
    shapes={}
    for col,cal in others:
        shapes.setdefault(norm_shape(cal),[]).append((col,cal))
    dup=[v for v in shapes.values() if len(v)>1]
    tgt=None
    if dup:
        def dL(cal):
            return min(abs(r-cr2)+abs(c-cc2) for r,c in cal for cr2,cc2 in Lcal)
        grp=max(dup,key=lambda v:len(v[0][1]))
        tgt=max(grp,key=lambda t:dL(t[1]))
    else:
        # strays (size<=2 or color appearing in tiny comps) are markers
        small={col for col,cal in others if len(cal)<=2 and len(cal)<len(Lcal)}
        cand=[(col,cal) for col,cal in others if col not in small or len(cal)>2]
        cand=[t for t in cand if len(t[1])>=2] or cand
        def dcorner(cal):
            return min(abs(r-cr)+abs(c-cc) for r,c in cal)
        tgt=max(cand,key=lambda t:(dcorner(t[1]),-len(t[1])))
    if tgt is None: return g
    for r,c in tgt[1]: g[r][c]=Lcol
    return g
'''
